INSERT OR REPLACE INTO LocalizedText(Language,Tag,Text) VALUES
 ('zh_Hans_CN','LOC_SPC_REST_TEAM','重组团队'),
 ('zh_Hans_CN','LOC_SPC_REST_TEAM_HELP','本城商业启用等级达到 4 级时可训练（仅能使用生产力组建）。可前往专业潜力至少为 2 级的己方城市，在其当前专业对应的区域执行「资产清算」（永久扣除该城 1 级专业潜力）；经过至少 5 个完整回合后，须在同一城市内另一个合格的专业区域执行「资产配置」并消耗本团队，完成专业转换（原专业的历史记录按各自规则保留）。此单位遭遇敌军时将自动撤退，不会被敌方俘获。'),
 ('zh_Hans_CN','LOC_SPC_REST_PHASE','资产重组中'),
 ('zh_Hans_CN','LOC_SPC_REST_LIQUIDATE','资产清算'),
 ('zh_Hans_CN','LOC_SPC_REST_CONFIGURE','资产配置'),
 ('zh_Hans_CN','LOC_SPC_REST_CONFIRM','确认{1_Name}'),
 ('zh_Hans_CN','LOC_SPC_REST_PREVIEW','目标城市：{1_City}[NEWLINE]清算后保留潜力：{2_Potential} 级[NEWLINE]执行「资产清算」将永久扣除该城 1 级专业潜力；资产重组期间，该城所有非食物产出及盈余食物增长均降低 75%。持续至少 5 个完整回合后，须将该团队移动至同城内另一个合格的专业区域，手动执行「资产配置」以完成重组。'),
 ('zh_Hans_CN','LOC_SPC_REST_WAIT','绑定城市：{1_City}[NEWLINE]当前保留潜力：{2_Potential} 级[NEWLINE]距离可执行「资产配置」还需等待 {3_Turns} 个完整回合（回合数届满后不会自动结束重组，须手动完成配置）。'),
 ('zh_Hans_CN','LOC_SPC_REST_MOVE','清算阶段：请将团队移动至专业潜力至少为 2 级的城市中，其当前专业对应的区域。[NEWLINE]配置阶段：请将团队移动至已绑定城市内另一个合格的专业区域。'),
 ('zh_Hans_CN','LOC_SPC_REST_PENDING','身份或事务尚未确认；请保留日志，不要重复确认。'),
 ('zh_Hans_CN','LOC_SPC_INSTITUTION_LEGACY','历史机构');
INSERT OR REPLACE INTO LocalizedText(Language,Tag,Text) VALUES
 ('zh_Hans_CN','LOC_SPC_REST_WAIT_GATE','尚未满5个完整回合。'),
 ('zh_Hans_CN','LOC_SPC_REST_CURRENT_SITE','请将团队移动至目标城市当前专业所对应的已建成且未被掠夺的区域。'),
 ('zh_Hans_CN','LOC_SPC_REST_OTHER_SITE','请将该团队移动至同一城市内另一个合格专业所对应的区域。'),
 ('zh_Hans_CN','LOC_SPC_REST_SAME_CITY','资产配置必须在已绑定的同一城市完成。'),
 ('zh_Hans_CN','LOC_SPC_REST_POTENTIAL_GATE','目标城市须至少拥有 2 级专业潜力，且当前没有待确认的移民专业化投资。');
-- Existing English fallback; authoritative player-facing copy remains Chinese.
INSERT OR REPLACE INTO LocalizedText(Language,Tag,Text)
 SELECT 'en_US',Tag,Text FROM LocalizedText WHERE Language='zh_Hans_CN' AND Tag LIKE 'LOC_SPC_REST_%';
INSERT OR REPLACE INTO LocalizedText(Language,Tag,Text) VALUES ('en_US','LOC_SPC_INSTITUTION_LEGACY','Historical Institution');
INSERT OR REPLACE INTO LocalizedText(Language,Tag,Text) VALUES ('zh_Hans_CN','LOC_SPC_COMMERCE_INSTITUTION_1','商贾聚落'),('en_US','LOC_SPC_COMMERCE_INSTITUTION_1','Merchant Settlement');
INSERT OR REPLACE INTO LocalizedText(Language,Tag,Text) VALUES ('zh_Hans_CN','LOC_SPC_COMMERCE_INSTITUTION_1_HELP','商人与经营活动逐渐汇聚，形成城市最初的商业共同体。[NEWLINE][NEWLINE]基础专家支持：[NEWLINE][ICON_BULLET] 每名在岗商业专家额外提供 +3 [ICON_Food] 食物和 +3 [ICON_Production] 生产力。'),('en_US','LOC_SPC_COMMERCE_INSTITUTION_1_HELP','Merchants gather here and form the city’s first trading community.[NEWLINE][NEWLINE]Basic Specialist Support:[NEWLINE][ICON_BULLET] Each working Commerce specialist provides +3 [ICON_Food] Food and +3 [ICON_Production] Production.');
INSERT OR REPLACE INTO LocalizedText(Language,Tag,Text) VALUES ('zh_Hans_CN','LOC_SPC_COMMERCE_INSTITUTION_2','同业公会'),('en_US','LOC_SPC_COMMERCE_INSTITUTION_2','Merchants’ Guild');
INSERT OR REPLACE INTO LocalizedText(Language,Tag,Text) VALUES ('zh_Hans_CN','LOC_SPC_COMMERCE_INSTITUTION_2_HELP','同业者建立稳定的组织，培养城市的商业人才。[NEWLINE][NEWLINE]同业制度：[NEWLINE][ICON_BULLET] 每名在岗商业专家额外提供 +2 基础 [ICON_GreatMerchant] 大商人点数。[NEWLINE][ICON_BULLET] 本城商业中心及其每一级合格建筑各 +1 [ICON_Housing] 住房。'),('en_US','LOC_SPC_COMMERCE_INSTITUTION_2_HELP','Merchants form guilds and train the next generation of traders.[NEWLINE][NEWLINE]Trade Associations:[NEWLINE][ICON_BULLET] Each working Commerce specialist provides +2 base [ICON_GreatMerchant] Great Merchant points.[NEWLINE][ICON_BULLET] Gain +1 [ICON_Housing] Housing from the Commercial Hub and +1 for each tier of eligible buildings it contains.');
INSERT OR REPLACE INTO LocalizedText(Language,Tag,Text) VALUES ('zh_Hans_CN','LOC_SPC_COMMERCE_INSTITUTION_3','交易所'),('en_US','LOC_SPC_COMMERCE_INSTITUTION_3','Exchange');
INSERT OR REPLACE INTO LocalizedText(Language,Tag,Text) VALUES ('zh_Hans_CN','LOC_SPC_COMMERCE_INSTITUTION_3_HELP','商人发现各领域的价值，也在投资中权衡时间与风险。[NEWLINE][NEWLINE]商业化：[NEWLINE][ICON_BULLET] 每名在岗商业专家可经营一个本城拥有对应区域的领域。取本城或直接国内商路相连的己方对应专业城市的最高产出，按本城对应区域的基础设施深度转化为额外 [ICON_Gold] 金币，不扣除来源产出。[NEWLINE][ICON_BULLET] 本城无需对应专业身份。相连城市须有对应身份，但无需启用。港口领域按总 [ICON_Food] 食物产出计算。[NEWLINE][NEWLINE]资本投资：[NEWLINE][ICON_BULLET] 可投资科研、文化或工业。本金为签约时国库的 25%，标准速度下 10 回合到期，每城每领域限一份未结合同。[NEWLINE][ICON_BULLET] 稳健投资返还本金与利润。风险投资成功时利润为稳健的 3 倍，失败返还 50% 本金，商业信誉可提高返还比例。'),('en_US','LOC_SPC_COMMERCE_INSTITUTION_3_HELP','Merchants find value across fields and weigh the risks of putting their capital to work.[NEWLINE][NEWLINE]Commercialization:[NEWLINE][ICON_BULLET] Each working Commerce specialist can commercialize one field for which this city has the corresponding district.[NEWLINE][ICON_BULLET] Earn extra [ICON_Gold] Gold based on the local district’s infrastructure depth and the highest eligible yield among this city and your cities of the matching specialization linked by a direct domestic Trade Route. Linked cities qualify even while their specialization is inactive. The Harbor field uses total [ICON_Food] Food. Source yields are retained.[NEWLINE][NEWLINE]Capital Investment:[NEWLINE][ICON_BULLET] Invest 25% of your Treasury in Research, Culture, or Industry. Each city can hold one unsettled contract per field. Contracts mature after 10 turns at Standard Speed.[NEWLINE][ICON_BULLET] Stable investments return principal and the quoted profit. A successful venture earns three times the stable profit. A failed venture returns 50% of principal, plus any Commercial Reputation bonus.');
INSERT OR REPLACE INTO LocalizedText(Language,Tag,Text) VALUES ('zh_Hans_CN','LOC_SPC_COMMERCE_INSTITUTION_4','资本信托'),('en_US','LOC_SPC_COMMERCE_INSTITUTION_4','Capital Trust');
INSERT OR REPLACE INTO LocalizedText(Language,Tag,Text) VALUES ('zh_Hans_CN','LOC_SPC_COMMERCE_INSTITUTION_4_HELP','资金沿商路投向新的建设，旧产业有了新的出路，信誉也在经营中逐渐积累。[NEWLINE][NEWLINE]发展投资：[NEWLINE][ICON_BULLET] 向本城发出的直接国内商路所连接的城市投资 [ICON_Gold] 金币。目标区域建造合格建筑时，+50% [ICON_Production] 生产力。下一座合格建筑完成后，合同结束。[NEWLINE][NEWLINE]资产重组：[NEWLINE][ICON_BULLET] 重组团队可在潜力至少二级的己方专业城市清算资产，永久扣除 1 级潜力。重组期间，非食物产出和用于人口增长的 [ICON_Food] 余粮减少 75%。[NEWLINE][ICON_BULLET] 计满 5 个完整回合后，须在同城另一合格专业区域手动配置资产，消耗团队并转换专业。[NEWLINE][NEWLINE]商业信誉：[NEWLINE][ICON_BULLET] 建立四级机构后，保有商业身份时每完整回合积累 1 点信誉，上限 40（标准速度）。转出商业后信誉清零。[NEWLINE][ICON_BULLET] 四级启用时，每点信誉使商业化收益 +0.5%，风险投资失败的本金返还比例提高 0.5 个百分点。最高分别为 +20% 和返还 70%。@SPC_METRIC@'),('en_US','LOC_SPC_COMMERCE_INSTITUTION_4_HELP','Investors fund new projects along trade routes, give old industries a fresh start, and build a reputation over time.[NEWLINE][NEWLINE]Development Investment:[NEWLINE][ICON_BULLET] Invest [ICON_Gold] Gold in a city reached by a direct domestic Trade Route from this city. Eligible buildings in the target district receive +50% [ICON_Production] Production. The contract ends when the next eligible building is completed.[NEWLINE][NEWLINE]Asset Restructuring:[NEWLINE][ICON_BULLET] An Asset Restructuring Team can liquidate assets in one of your specialized cities with Potential at Level 2 or higher. This permanently lowers that city''s Potential by 1 level. During restructuring, non-Food yields and [ICON_Food] surplus Food used for growth are reduced by 75%.[NEWLINE][ICON_BULLET] After 5 full turns, use the team to allocate assets in another eligible district in the same city. This consumes the team and changes the city''s specialization.[NEWLINE][NEWLINE]Commercial Reputation:[NEWLINE][ICON_BULLET] Once the Level 4 institution is established, the city earns 1 Reputation per full turn while it specializes in Commerce, up to 40 at Standard Speed. It loses its Reputation if it leaves Commerce.[NEWLINE][ICON_BULLET] While Commerce is active at Level 4, each point of Reputation increases Gold from Commercialization by 0.5% and the share of principal returned after a failed Venture Investment by 0.5 percentage points. At the cap, income is 20% higher and failed Venture Investments return 70% of principal.@SPC_METRIC@');
